package ru.fifth.horror.item;
import net.minecraft.entity.player.PlayerEntity;import net.minecraft.item.Item;import net.minecraft.item.ItemUsageContext;import net.minecraft.text.Text;import net.minecraft.util.ActionResult;import ru.fifth.horror.entity.MonsterForLiftEntity;
public final class MflPathToolItem extends Item{public MflPathToolItem(Settings s){super(s);}public static ActionResult select(net.minecraft.item.ItemStack st,PlayerEntity p,MonsterForLiftEntity m){if(!p.getWorld().isClient){st.getOrCreateNbt().putUuid("FivenMflUuid",m.getUuid());p.sendMessage(Text.literal("§8[§cFiven§8] §7MFL выбран. Теперь кликай по блокам для точек маршрута."),true);}return ActionResult.SUCCESS;}@Override public ActionResult useOnBlock(ItemUsageContext c){PlayerEntity p=c.getPlayer();if(p==null)return ActionResult.PASS;if(c.getWorld().isClient)return ActionResult.SUCCESS;var n=c.getStack().getOrCreateNbt();if(!n.containsUuid("FivenMflUuid")){p.sendMessage(Text.literal("§cСначала выбери MFL."),true);return ActionResult.SUCCESS;}var e=((net.minecraft.server.world.ServerWorld)c.getWorld()).getEntity(n.getUuid("FivenMflUuid"));if(e instanceof MonsterForLiftEntity m){if(p.isSneaking()){m.clearRoute();p.sendMessage(Text.literal("§7Маршрут MFL очищен."),true);}else{m.addRoutePoint(c.getHitPos());p.sendMessage(Text.literal("§7Точка MFL #"+m.getRoute().size()+" добавлена."),true);}}return ActionResult.SUCCESS;}}
